-- Create "api_tokens" table
CREATE TABLE "public"."api_tokens" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "prefix" character varying NOT NULL,
  "secret_hash" character varying NOT NULL,
  "scopes" jsonb NOT NULL,
  "expires_at" timestamptz NULL,
  "revoked_at" timestamptz NULL,
  "last_used_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "api_tokens_prefix_key" to table: "api_tokens"
CREATE UNIQUE INDEX "api_tokens_prefix_key" ON "public"."api_tokens" ("prefix");
-- Create "contacts" table
CREATE TABLE "public"."contacts" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "email" character varying NOT NULL,
  "first_name" character varying NULL,
  "last_name" character varying NULL,
  "status" character varying NOT NULL DEFAULT 'active',
  "time_zone" character varying NULL,
  "custom_fields" jsonb NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "contacts_email_key" to table: "contacts"
CREATE UNIQUE INDEX "contacts_email_key" ON "public"."contacts" ("email");
-- Create "events" table
CREATE TABLE "public"."events" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "subject_id" character varying NOT NULL,
  "email" character varying NULL,
  "phone" character varying NULL,
  "action" character varying NOT NULL,
  "properties" jsonb NULL,
  "occurred_at" timestamptz NULL,
  "prospect" boolean NULL,
  "created_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create "tracking_profiles" table
CREATE TABLE "public"."tracking_profiles" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "subject_id" character varying NOT NULL,
  "email" character varying NULL,
  "phone" character varying NULL,
  "traits" jsonb NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "tracking_profiles_email_key" to table: "tracking_profiles"
CREATE UNIQUE INDEX "tracking_profiles_email_key" ON "public"."tracking_profiles" ("email");
-- Create index "tracking_profiles_phone_key" to table: "tracking_profiles"
CREATE UNIQUE INDEX "tracking_profiles_phone_key" ON "public"."tracking_profiles" ("phone");
-- Create index "tracking_profiles_subject_id_key" to table: "tracking_profiles"
CREATE UNIQUE INDEX "tracking_profiles_subject_id_key" ON "public"."tracking_profiles" ("subject_id");
-- Create "users" table
CREATE TABLE "public"."users" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "email" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Create index "users_email_key" to table: "users"
CREATE UNIQUE INDEX "users_email_key" ON "public"."users" ("email");
-- Create "tracking_visitors" table
CREATE TABLE "public"."tracking_visitors" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "visitor_id" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "last_seen_at" timestamptz NOT NULL,
  "profile_id" bigint NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "tracking_visitors_tracking_profiles_visitors" FOREIGN KEY ("profile_id") REFERENCES "public"."tracking_profiles" ("id") ON UPDATE NO ACTION ON DELETE SET NULL
);
-- Create index "tracking_visitors_visitor_id_key" to table: "tracking_visitors"
CREATE UNIQUE INDEX "tracking_visitors_visitor_id_key" ON "public"."tracking_visitors" ("visitor_id");
